import React from 'react';

function Explore() {
  return (
    <div className="container" style={{ padding: 20 }}>
      <h1>🔎 탐색 (카테고리)</h1>
      <p style={{ color: '#555' }}>카테고리별로 리뷰를 필터링하여 보여주는 페이지입니다. (뷰티 · 패션 · 생활용품 등)</p>

      <div style={{ marginTop: 18 }}>
        <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
          <button className="btn" style={{ padding: '8px 12px', borderRadius: 12, border: '1px solid #e6eefb' }}>#뷰티</button>
          <button className="btn" style={{ padding: '8px 12px', borderRadius: 12, border: '1px solid #e6eefb' }}>#패션</button>
          <button className="btn" style={{ padding: '8px 12px', borderRadius: 12, border: '1px solid #e6eefb' }}>#F&B</button>
          <button className="btn" style={{ padding: '8px 12px', borderRadius: 12, border: '1px solid #e6eefb' }}>#라이프스타일</button>
        </div>

        <div style={{ marginTop: 20 }}>
          <p className="muted">여기에 카테고리 필터링 결과가 표시됩니다. 원하시면 샘플 필터 결과(그리드)를 추가해 드리겠습니다.</p>
        </div>
      </div>
    </div>
  );
}

export default Explore;
